use std::collections::hash_map::Entry;
use std::collections::HashMap;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Row {
    pub endpoint: String,
    pub count: u64,
    pub errors: u64,
    pub bytes: u128,
}

#[derive(Debug, PartialEq, Eq)]
pub struct Output {
    pub rows: Vec<Row>,
    pub invalid: u64,
}

#[inline]
fn parse_bytes(text: &[u8]) -> Option<u64> {
    if text.is_empty() {
        return None;
    }
    let mut value = 0u64;
    if text.len() <= 19 {
        // Every sequence of at most 19 decimal digits fits in u64.
        for &byte in text {
            let digit = byte.wrapping_sub(b'0');
            if digit > 9 {
                return None;
            }
            value = value * 10 + u64::from(digit);
        }
    } else {
        // Length cannot reject arbitrarily many leading zeroes.
        for &byte in text {
            let digit = byte.wrapping_sub(b'0');
            if digit > 9 {
                return None;
            }
            value = value.checked_mul(10)?.checked_add(u64::from(digit))?;
        }
    }
    Some(value)
}

#[inline]
fn parse_record(line: &str) -> Option<(&str, bool, u64)> {
    if !line.starts_with('/') {
        return None;
    }
    // Use the standard delimiter search. Endpoint control validation is
    // performed on first insertion, since every existing key passed it.
    let (endpoint, fields) = line.split_once('\t')?;
    let text = fields.as_bytes();
    let mut pos = 0;
    let mut status = 0u16;
    while pos < text.len() && text[pos] != b'\t' {
        let digit = text[pos].wrapping_sub(b'0');
        if digit > 9 {
            return None;
        }
        status = status * 10 + u16::from(digit);
        if status > 599 {
            return None;
        }
        pos += 1;
    }
    if pos == text.len() || pos == 0 || status < 100 {
        return None;
    }
    // Additional TABs are rejected by the ASCII digit grammar.
    let bytes = parse_bytes(&text[pos + 1..])?;
    Some((endpoint, status >= 400, bytes))
}

// Contract: UTF-8 input; lines separated by LF, optional single terminal CR.
// Exactly 3 TAB-separated fields; nonempty endpoint starting '/' and no controls.
// ASCII digits only; status 100..599; bytes 0..u64::MAX; u128 aggregate sum.
// Empty input has no rows. A final LF terminates rather than adds an empty row.
pub fn aggregate(input: &str) -> Output {
    // Retain the standard randomized hasher for untrusted input. Only valid
    // endpoint keys enter this per-call map; no state survives the call.
    let mut map: HashMap<&str, (u64, u64, u128)> = HashMap::new();
    let mut invalid = 0;

    for raw in input.split_terminator('\n') {
        let line = raw.strip_suffix('\r').unwrap_or(raw);
        let Some((endpoint, is_error, bytes)) = parse_record(line) else {
            invalid += 1;
            continue;
        };
        match map.entry(endpoint) {
            Entry::Occupied(mut entry) => {
                // String equality is exact: this same endpoint has already
                // passed the full Unicode control-character predicate.
                let item = entry.get_mut();
                item.0 += 1;
                item.1 += u64::from(is_error);
                item.2 += bytes as u128;
            }
            Entry::Vacant(entry) => {
                if endpoint.chars().any(|c| c.is_control()) {
                    invalid += 1;
                    continue;
                }
                entry.insert((1, u64::from(is_error), bytes as u128));
            }
        }
    }

    let mut rows: Vec<Row> = map
        .into_iter()
        .map(|(endpoint, (count, errors, bytes))| Row {
            endpoint: endpoint.to_owned(),
            count,
            errors,
            bytes,
        })
        .collect();
    rows.sort_unstable_by(|a, b| a.endpoint.cmp(&b.endpoint));
    Output { rows, invalid }
}
